#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
sdk_pybind_ros_rt_topics_example.py

Subscribes to standard ROS-style messages published on the Booster RT DDS topics
(see b1_api_const.hpp::kTopicRos*), using the same ChannelFactory as other examples:

  - B1RosOdometrySubscriber  -> kTopicRosOdometer  (default: "rt/odom")
  - B1RosImuSubscriber       -> kTopicRosImu       (default: "rt/imu/data")
  - B1RosJointStateSubscriber -> kTopicRosJointStates (default: "rt/joint_states")

Prerequisites: motion (or another node) publishing these topics on the same DDS domain.

Options:
  --domain-id     DDS domain id (default: 0)
  --iface         DDS network interface (default: empty)
  --robot-name    If set, topic becomes rt/<name>/odom|imu/data|joint_states
  --subs          Comma-separated: ros_odom, ros_imu, ros_joint, all, none (default: all)

Example:
  python3 sdk_pybind_ros_rt_topics_example.py
  python3 sdk_pybind_ros_rt_topics_example.py --subs ros_odom,ros_imu
  python3 sdk_pybind_ros_rt_topics_example.py --robot-name mybot
"""

import argparse
import signal
import sys
import time

try:
    import booster_robotics_sdk_python as br
except ImportError:
    try:
        import _core as br
    except ImportError:
        print(
            "Error: 'booster_robotics_sdk_python' or '_core' not found. "
            "Install the wheel or set PYTHONPATH to the built _core location."
        )
        sys.exit(1)


# ========== DDS ==========


def init_dds(domain_id: int = 0, iface: str = "") -> None:
    br.ChannelFactory.Instance().Init(domain_id, iface)


# ========== Callbacks (RosOdometry / RosImu / RosJointState) ==========


def on_ros_odom(msg: br.RosOdometry) -> None:
    p = msg.pose.pose.position
    v = msg.twist.twist.linear
    print(
        f"[RosOdometry] frame={msg.header.frame_id!r} child={msg.child_frame_id!r} "
        f"xyz=({p.x:.4f},{p.y:.4f},{p.z:.4f}) v=({v.x:.4f},{v.y:.4f},{v.z:.4f})"
    )


def on_ros_imu(msg: br.RosImu) -> None:
    w = msg.angular_velocity
    a = msg.linear_acceleration
    q = msg.orientation
    print(
        f"[RosImu] gyro=({w.x:.4f},{w.y:.4f},{w.z:.4f}) "
        f"acc=({a.x:.4f},{a.y:.4f},{a.z:.4f}) "
        f"quat=({q.x:.4f},{q.y:.4f},{q.z:.4f},{q.w:.4f})"
    )


def on_ros_joint(msg: br.RosJointState) -> None:
    names = msg.name
    pos = msg.position
    n = len(names)
    head_n = min(6, n)
    preview = []
    for i in range(head_n):
        preview.append(f"{names[i]}:{pos[i]:.4f}" if i < len(pos) else names[i])
    extra = f" ... (+{n - head_n} joints)" if n > head_n else ""
    print(f"[RosJointState] n={n} {preview}{extra}")


# ========== CLI ==========


def parse_args():
    p = argparse.ArgumentParser(
        description="Subscribe to rt/odom, rt/imu/data, rt/joint_states (ROS-shaped DDS)"
    )
    p.add_argument("--domain-id", type=int, default=0)
    p.add_argument("--iface", type=str, default="")
    p.add_argument(
        "--robot-name",
        type=str,
        default="",
        help="Prefix robot name into rt/<name>/... topics (optional)",
    )
    p.add_argument(
        "--subs",
        type=str,
        default="all",
        help="ros_odom, ros_imu, ros_joint, all, none",
    )
    return p.parse_args()


def parse_subs(raw: str, valid: set) -> set:
    s = raw.strip().lower()
    if s == "all":
        return set(valid)
    if s == "none" or not s:
        return set()
    out = set()
    for item in s.split(","):
        item = item.strip()
        if not item:
            continue
        if item in valid:
            out.add(item)
        else:
            print(f"[Warn] unknown subs key '{item}', ignored.")
    return out


def main() -> None:
    args = parse_args()
    valid = {"ros_odom", "ros_imu", "ros_joint"}
    enabled = parse_subs(args.subs, valid)

    if not enabled:
        print("No subscriptions selected (use --subs all or ros_odom,ros_imu,ros_joint). Exit.")
        return

    print("Enabled subscriptions:", sorted(enabled))
    if getattr(br, "kTopicRosOdometer", None):
        print(
            "Topics:",
            br.kTopicRosOdometer,
            br.kTopicRosImu,
            br.kTopicRosJointStates,
        )

    init_dds(domain_id=args.domain_id, iface=args.iface)

    subs = []
    robot_name = (args.robot_name or "").strip()

    if "ros_odom" in enabled:
        s = br.B1RosOdometrySubscriber(on_ros_odom)
        if robot_name:
            s.InitChannelWithName(robot_name)
        else:
            s.InitChannel()
        subs.append(s)
        print(f"[RosOdometry] channel={s.GetChannelName()}")

    if "ros_imu" in enabled:
        s = br.B1RosImuSubscriber(on_ros_imu)
        if robot_name:
            s.InitChannelWithName(robot_name)
        else:
            s.InitChannel()
        subs.append(s)
        print(f"[RosImu] channel={s.GetChannelName()}")

    if "ros_joint" in enabled:
        s = br.B1RosJointStateSubscriber(on_ros_joint)
        if robot_name:
            s.InitChannelWithName(robot_name)
        else:
            s.InitChannel()
        subs.append(s)
        print(f"[RosJointState] channel={s.GetChannelName()}")

    running = True

    def handle_sigint(_sig, _frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, handle_sigint)

    print("\nListening. Ctrl+C to exit.\n")
    dt = 0.05
    try:
        while running:
            time.sleep(dt)
    finally:
        print("\nClosing...")
        for s in subs:
            s.CloseChannel()
        print("Done.")


if __name__ == "__main__":
    main()
